CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS departments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(255));
CREATE TABLE IF NOT EXISTS doctors (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, phone VARCHAR(255), specialization VARCHAR(255), department_id BIGINT NOT NULL REFERENCES departments(id), user_id BIGINT NOT NULL UNIQUE REFERENCES users(id));
CREATE TABLE IF NOT EXISTS time_slots (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, booked BOOLEAN NOT NULL DEFAULT FALSE, date DATE NOT NULL, end_time TIME NOT NULL, start_time TIME NOT NULL, doctor_id BIGINT NOT NULL REFERENCES doctors(id));
CREATE TABLE IF NOT EXISTS appointments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ai_summary TEXT, created_at TIMESTAMP, notes VARCHAR(255), status VARCHAR(255), doctor_id BIGINT NOT NULL REFERENCES doctors(id), patient_id BIGINT NOT NULL REFERENCES users(id), slot_id BIGINT NOT NULL REFERENCES time_slots(id));
ALTER TABLE users ADD COLUMN IF NOT EXISTS active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE appointments DROP CONSTRAINT IF EXISTS uk8y6yin1cflvk14414e91mdcwm;
ALTER TABLE appointments DROP CONSTRAINT IF EXISTS appointments_status_check;
ALTER TABLE appointments ADD CONSTRAINT appointments_status_check CHECK (status IN ('PENDING','CONFIRMED','CANCELLED','COMPLETED','NO_SHOW'));
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS diagnosis TEXT;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS prescription TEXT;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS follow_up DATE;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS shared BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS reminder_sent BOOLEAN NOT NULL DEFAULT FALSE;
CREATE INDEX IF NOT EXISTS idx_appointments_slot ON appointments(slot_id);
CREATE INDEX IF NOT EXISTS idx_slots_doctor_date ON time_slots(doctor_id,date);
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), expires_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS password_resets (token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), expires_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS email_outbox (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient VARCHAR(255) NOT NULL, subject VARCHAR(255) NOT NULL, body TEXT NOT NULL, sent_at TIMESTAMP, attempts INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
